quests[50493] = { id = 50493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetching Wrex", description = "When all the commotion started, Ancel's pup ran off. The poor thing was terrified!\n\nA couple farmhands went to look for him, but with all of these monsters terrorizing the farm, I fear the worst!\n\nCan you keep an eye out for Wrex while you're up in the hills? He might have gotten trapped in the honey too.", completion = "Ancel will be happy to know that Wrex is safe and sound!", objectives = "Crack open Crystallized Honey to search for Wrex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
