quests[50529] = { id = 50529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits Within" }
quests[50530] = { id = 50530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witch Way Out?", description = "There are other Falconhurst citizens to be freed before they become sacrifices.\n\nFree anyone you come across.\n\nThe key used to free Master Ashton should still work. Good luck!", completion = "Well done! Not only did you save innocents, you denied the witches fuel for their Grand Rite.", objectives = "Free 10 Captive Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50531] = { id = 50531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Their Noses", description = "Figures they wouldn't just put the destination on the crates for us. \n\nNothing's ever easy, is it?\n\nIf the weapons aren't moving on Cagney's ferry, they must be passing through Bridgeport, the shipping hub just up the road.\n\nBridgeport is protected by a garrison of Proudmoore marines. The Ashvane Company has a lot of nerve moving illegal weapons right under their noses.\n\nCome on, let's check it out.", completion = "<Flynn pretends not to notice you, but whispers at you.>\n\nOf course it's her.", objectives = "Speak with Flynn Fairwind in Bridgeport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50533] = { id = 50533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stick It To 'Em!", description = "We have been able to stop the Grand Rite but the witches will try again unless we act.\n\nWe have to destroy them. Utterly.\n\n<Cleardawn smiles.>\n\nHow kind of them to give us the means.\n\nYou've helped us get this far, {name}. You control the Demolisher. Destroy everything you see! \n\nOnce we've finished we can signal for help out of here!", completion = "The plans for the Grand Rite are ruined and their rutial sites are in shambles. Master Ashton will be safe here in Arom's stand and we can finally send reinforcements to Falconhurst by gryphon.\n\nIn all, a job well done! Thank you for your vital help.", objectives = "Use the Crimsonwood Demolisher to destroy witch forces in the Crimson Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50534] = { id = 50534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wendigo Away", description = "If the unearthly howls coming from the Highlands at night are any indication, the wendigos must have some sort of leader or alpha.\n\nI tell you, it's the sort of sound that could only come from some sort of massive, hulking, flesh-eating abomination.\n\nDefinitely something that could tear us limb from limb, and munch on our frail bones, all without breaking a sweat. How exhilarating!\n\nI'm sure it'll be no problem for us to handle though.", completion = "Marvelous! Slaying their leader ought to put some fear into 'em.", objectives = "Kill Bonerender.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50535] = { id = 50535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Overseer", description = "Overseer Nerzet is very cruel, and oh so easy to provoke!  \n\nIt makes her very angry when things go missing, or move, or change... my crew and I are having a yip of a time! That you got this device to work was certainly a bonus!\n\nIt will be much easier for us to finish up what we need to do here, with her out of the way. \n\nUm, and maybe go ahead and grab that neat power rock she carries. It could come in handy.", progress = "Were you able to end her reign?", completion = "Hmmm. I am tempted to sell this stone, it must be quite valuable. \n\nHowever, with what you have shown us today, I think there may be more value in having it with us.", objectives = "Kill Overseer Nerzet and take her power rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50536] = { id = 50536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magic Decoder Device", description = "We retrieved this device from the sethrak in the ruins to the east, but have not been able to use it.\n\nWhen you approached, it started to glow. Something about you...\n\n<Maaz pauses and eyes the stone on your neck.>\n\n...or on you... is waking it up!\n\nPlease, {class}, use the scepter and examine the statues of the Keepers, in the central courtyard of the ruins. Something there got their overseer very excited.", progress = "What did you discover?", completion = "Oh, thank you, danger noodle. This will give us just the angle we need to get the most out of what we find here. Your arrival was most fortuitous!", objectives = "Examine the Keeper statues in the ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50538] = { id = 50538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Handler", description = "I just received word from Warbeast Kraal dat one of their handlers is missing.\n\nDis is not usually a problem, but dey are expecting a large hatching dis year. Dey will need all de hands dey can get!\n\nGo on and see if you can find de handler, name of Bazo or something, and tell him to get back to de Kraal.", completion = "<Handler Bazkoji rests with his sword still held in hand. He died fighting.>", objectives = "Look for Handler Bazkoji near Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50539] = { id = 50539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Zul'Ahjin", description = "You're not the only one who came to Zul'Ahjin looking for answers. The place is crawling with looters and assassins, all searching for something... \n\nSo far, they've come up empty handed, but that's because they don't know where to look.\n\nI do. \n\nInvestigate the statue at the center of the ruins. It is the key to uncovering the city's ancient secrets.", completion = "<The ancient stones hum with magic.>", objectives = "Investigate the statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50540] = { id = 50540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Rastari" }
quests[50542] = { id = 50542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Explosive Opportunity", description = "You there!\n\nDo I have the most AMAZING opportunity for you? A gnome named Wulferd Fizzbracket is on the eve of a breakthrough and could use an intrepid business partner that's on the brawnier side. Such as a {class} like yourself.\n\nJust follow the road east until you reach Fizzsprings Resort, the most fantastical wonder of nature. Wulferd is the type that stands out from the crowd.", completion = "A willing assistant? Well I can't turn you down now, can I?", objectives = "Speak with Wulferd Fizzbracket at the Fizzsprings Resort.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50544] = { id = 50544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunters of Kennings Lodge", description = "HELP WANTED!\n\nAs we turn into the busy season, Kennings Lodge is looking for recreational hunters to assist with fulfilling the ever growing list of orders from Boralus. These are short term positions which will be paid relative to performance. \n\nKennings Lodge can be found by following the south road past the mining yard. Report to Alanna Holton on arrival.", completion = "You came from Bridgeport? Let's get you working, then.", objectives = "Speak with Alanna Holton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50545] = { id = 50545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forked Lightning" }
quests[50547] = { id = 50547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knives of Zul" }
quests[50548] = { id = 50548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enforcing the Will of the King" }
quests[50549] = { id = 50549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolutely Barbaric" }
quests[50550] = { id = 50550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Emperor Korthek", description = "Korthek finally approaches.\n\nIt's been many years since I've faced him in battle. When he first rose to power, I failed my people. I will not falter again.\n\nI am prepared to do what must be done. What I should have done long ago.\n\nWe must kill Korthek and take his key to prevent him, Jakra'zet, or anyone else from ever resurrecting Mythrax.\n\nWhen you are prepared, we will face him together.", completion = "Do not waste time mourning my old friend now. His foolish crusade has left us a larger problem that demands our full, immediate attention.", objectives = "Defeat Emperor Korthek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50551] = { id = 50551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple of Sethraliss: Avatar of the Loa", description = "We cannot let Mythrax bring his destruction upon this world once more. \n\nWe need our loa now more than ever, but she has yet to return to us.\n\nThe time of her rebirth has passed. Someone, or something, must be preventing her awakening.\n\nEnter her resting place and see what you can uncover.", progress = "We cannot let Mythrax bring his destruction upon this world once more.", completion = "Behold, {name}. Sethraliss has returned.", objectives = "Enter the Temple of Sethraliss and heal the avatar of the loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50553] = { id = 50553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Lab", completion = "Well, we had quite the adventure {name}.\n\nLet's try not to do that again anytime soon though!", objectives = "Meet Raimond Mildenhall in his Raimond's Laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50559] = { id = 50559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Out of Hand" }
quests[50561] = { id = 50561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sulthis' Stone", description = "<The ancient reliquary contains a single stone, humming with magic. Perhaps Serrik will know what it is?>", progress = "What have you found?", completion = "This stone... I've seen one like it before.", objectives = "Deliver Sulthis' Stone to Serrik within Zul'Ahjin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50562] = { id = 50562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of Azeroth", description = "Assist Magni by completing 4 Azerite world quests.", progress = "Return to me when you have finished aiding Azeroth, {name}.", completion = "Azeroth and myself thank you.", objectives = "Complete 4 Azerite world quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
