quests[50573] = { id = 50573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message from the Management", description = "<This letter from Priscilla Ashvane to her employees appears to be posted all over the foundry.\n\nIt sounds like Cagney's information was accurate, Ashvane is working their people around the clock.\n\nPriscilla mentions a Forgemaster Farthing and a Taskmaster Williams. They may have more information about her plans.>", progress = "Find anything useful in there?", completion = "Most folks workin' for the Ashvane Trading Company don't know how rotten they are, or don't have any other choice.\n\nThe sooner we take down Priscilla the better.", objectives = "Collect Priscilla's Orders from Forgemaster Farthing and Taskmaster Williams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50574] = { id = 50574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservation Methods" }
