quests[50581] = { id = 50581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrolls and Scales" }
quests[50583] = { id = 50583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Other Side", description = "It looks like the coven is using Corlain as a base of operations. There's no way we'll be able to cut through this many of them without the rest of the Inquisitors.\n\nThey must still be stuck behind the wall. \n\n{class}, there are three smaller footmen gates along the walls into Corlain. See if you can get them open so our allies can make their way through.", progress = "What news of the other inquisitors?", completion = "All here and accounted for?\n\nVery well, we've no time to waste. We must ride to Waycrest Manor!", objectives = "Open the Eastern, Southern, and Western Gates in Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50584] = { id = 50584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinous Rituals", description = "Take a look in the city square, {class}.\n\n<Marshal Reade gestures toward a ritual being performed by some disciples in the distance.>\n\nIt appears the coven has gone beyond dark constructs, and are now conjuring creatures of nightmare with their rituals. Let us not wait to see what these monsters are capable of. We should put an end to them right here.\n\nFortunately, the disciples seem too focused on their spell to notice us. Maybe you can use that to your advantage.", progress = "Have the monsters been abolished?", completion = "I am glad we were able to stop those things here, before the coven could unleash them on Drustvar's unsuspecting citizens.", objectives = "Kill 4 Blighted Horrors in Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50585] = { id = 50585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexecutioner", description = "It would appear that this is where the coven is training their new acolytes. Our efforts may be for naught if they continue to expand their numbers.\n\nI cannot leave Lucille's side in this place, but you have already shown yourself a formidable combatant. \n\nCut them down.", completion = "The people of Drustvar will sleep more soundly with less witches in the world.", objectives = "Kill 13 witches of the Heartsbane Coven in Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50586] = { id = 50586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Corlain", description = "<This discarded journal looks like it belonged to one of the residents of upper Corlain. Within it details some early signs of the Heartsbane's appearance in Corlain.\n\nIf you can find more writings like this, you might be able to piece together the events that led to Corlain's current state.>", completion = "This tale... such a tragic fate to befall my home...\n\nWe must make this right, {class}!  For the people of Corlain and all of Drustvar!", objectives = "Examine 6 Corlain Citizen's Journals in Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50587] = { id = 50587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagative Feedback" }
quests[50588] = { id = 50588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Manor", description = "Now is our chance. Waycrest Manor is just up that hill, and hopefully inside we'll find my mother and father. \n\nIf we also manage to find the \"Mother\" that's leading this horrible coven, then we will make her regret the day she ever set foot in Drustvar.\n\nAre you with me, {class}?", completion = "I'm sorry... this is all a bit too much...\n\nThank you, {class}, for protecting me.  I think I'm going to need a moment...", objectives = "Follow Lucille Waycrest toward Waycrest Manor in Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50591] = { id = 50591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Son of a Bee" }
quests[50592] = { id = 50592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiny Terror" }
quests[50593] = { id = 50593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Mess", description = "<The vial is filled with a viscous, bubbling substance. It bears a striking resemblance to the animated horrors around you.\n\nIt struggles against the container, as if trying to escape. Pike would surely be interested in more samples.>", progress = "What is that you have there?", completion = "This tideblood is saturated with dark magic. Thank you for bringing it to me.", objectives = "Collect 20 Tideblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50594] = { id = 50594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Veil", description = "We must board the Abyssal Melody and save the myriad souls in her decks before they too disappear into the Shrine. We will not be able to enter so long as the barrier surrounding it stands.\n\nThe tidesages are using forbidden magic to summon extensions of their will. It is these grasps that maintain the barrier.\n\nTake my beacon and mark each grasp. I will rain vengeance down upon them from here.", progress = "Have the grasps been dealt with?", completion = "The Abyssal Melody lies unprotected. Now is our chance.", objectives = "Use the Abyssal Beacon to dispel the Writhing Grasps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50595] = { id = 50595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Quarter", description = "We arrived just in time. These abominations have already taken control of the docks; we're all that's left to keep them at bay!\n\nYou need to cull their numbers before we're overwhelmed. We don't exactly have an army here!", completion = "We're holding out alright thanks to you, but Sam is still missing!", objectives = "Kill 8 Skeletal Sailors and 4 Tidesage Seacallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50596] = { id = 50596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminate the Vermin", description = "On top of the fury of the overseer, and this \"key\" not being here, we have a pest problem.\n\nSneaky little vulperan thieves keep ransacking our site. We have taken some prisoner.\n\nWe have them around the upper level of the dig site, working off their misdeeds. However, I believe a more permanent solution would be preferred. \n\nPlease, oh mighty cobra, give us the honor of getting rid of our prisoners with your most potent venom!", progress = "They had what?", completion = "Well played on the rescue. I can't decide if you're clever, or they're stupid. I like your odds, though!", objectives = "Rescue 3 captive excavators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50598] = { id = 50598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalari Empire", description = "Assist the Zandalari Empire in Zuldazar by completing 4 world quests.", progress = "Return to me when you have finished aiding da Zandalari Empire, {name}.", completion = "Da Zandalari Empire thanks you.", objectives = "Complete any 4 world quests in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
