quests[50605] = { id = 50605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance War Effort", description = "Assist the Alliance by completing 4 world quests on Zandalar or occupied warfront zones.", progress = "Return to me when you have finished aiding the Alliance, {name}.", completion = "For the Alliance!", objectives = "Complete 4 world quests on Zandalar or occupied warfront zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50606] = { id = 50606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde War Effort", description = "Assist the Horde by completing 4 world quests on Kul Tiras or occupied warfront zones.", progress = "Return to me when you have finished aiding the Horde, {name}.", completion = "For the Horde!", objectives = "Complete 4 world quests on Kul Tiras or occupied warfront zones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50608] = { id = 50608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Rites", description = "These k'thir have been hiding among us, sowing the seeds of their dark masters with us none the wiser.\n\nWith the barrier around the Abyssal Melody lowered I can peer within; its bowels toil with my own people giving themselves to the shadow!\n\nTake my tidal kris; its blade is now coated in purified tideblood. Put an end to these fiends and their foul rituals.", completion = "Good. Each death brings this valley one step closer to redemption.", objectives = "Kill 15 K'thir and disrupt 6 rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50609] = { id = 50609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Maw of Madness", description = "Sam is still out there somewhere. We can't just leave him to die!\n\nIf he wasn't in the assembly yard, he must be on that ship. You have to find him!", completion = "That was a tight spot you got me out of back there. I owe ya my life.", objectives = "Find Samuel Williams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50610] = { id = 50610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Storm", description = "This depravity goes against every oath we take as tidesages. To protect our people... to guide and sustain them... to make our ships strong.\n\nThis is nothing but darkness. It must all be destroyed.\n\nBoard the Abyssal Melody and place these focusing rods at any critical points you find. I will prepare the ritual.", completion = "Now to finish the deed.", objectives = "Place 4 Focusing Rods on the Abyssal Melody.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50611] = { id = 50611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's Vengeance", description = "I know not what horrors await us ahead, but the Abyssal Melody must never follow its sister into the Shrine of the Storm.\n\nWe will deny these monsters all that they have wrought here by burning it with the very magic they seek to corrupt.\n\nThe ritual is ready, but requires a conduit to stabilize. If you are willing, I would have you guide my magic.", progress = "Whenever you are ready.", completion = "A pivotal step, but our work is far from finished.", objectives = "Destroy the Abyssal Melody.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50612] = { id = 50612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A House Divided", description = "Not all of House Stormsong have followed my Lord down this dark path. They know not - I knew not - the truth of his depravity.\n\nSagehold looms above us. It is where all tidesages study to wield the sea's power.\n\nWe will build upon the Storm's Wake and make my shattered home whole once more. We will save all who are willing. \n\nThe rest will perish.", completion = "With any luck we will end this matter here.", objectives = "Join Brother Pike outside Sagehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50614] = { id = 50614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for the Sea", description = "The naga along this coast appear to be trying to push the shoreline up the hill here. We've been able to keep them back at the beach so far, but they've been binding more elementals than we can keep up with.\n\nWithout a tidesage, we have no way to free the elementals from their bindings, but we cannot allow them to push forward anymore. The spirit of the sea should not be contained by anything. Slay them, and let them return to the ocean.", progress = "For a people that live in the sea, the naga seem to have little respect for it.", completion = "That should slow down their progress quite a bit. You have my gratitude.", objectives = "Slay 6 Bound Seasurges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50616] = { id = 50616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of a Bind", description = "The naga sorceress leading this excursion seems to be in the process of binding a larger elemental. If she succeeds, we will no doubt lose our foothold here.\n\nStrike out at her, perhaps you can catch her off guard and interrupt the ritual. Remove the head from these snakes.", progress = "Is the seawitch dead?", completion = "I have no idea what this might be, but I don't like the looks of it.", objectives = "Slay Binder Sa'thress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50617] = { id = 50617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atul'Aman", description = "Jakra'zet and his troops attacked while we were away. \n\nSerrik fought well, but it wasn't enough. The keys are gone, and it's only a matter of time before the barrier is broken.\n\nYour friends have already given chase. \n\nJakra'zet must not be allowed to resurrect Mythrax the Unraveler. He must be stopped before it's too late!\n\nWe don't have much time. \n\nMeet me at Atul'Aman! We must catch up with Kaja and Rakera and stop the ritual!", completion = "We must hurry. Your friends are already inside!", objectives = "Meet Vorrik at Atul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50619] = { id = 50619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Goes Up" }
quests[50621] = { id = 50621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught in the Net", description = "When the naga force first arrived, there were a handful of the local fishermen out on boats. One of our scouts reports that most of them have been captured and are currently being kept in cages around the beach.\n\nFree any of them you happen to find and point them back here. We'll get them armed and remind the naga that you don't mess with sailors!", completion = "With these numbers, we should be able to hold our own here. Oars and fishing nets make surprisingly effective weapons.", objectives = "Free 5 villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50622] = { id = 50622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deal's Off", description = "There's one more farm left, far to the west. They're real close to the kraul.\n\nDeal works the land by herself. If anyone got hit bad, it'd be her. It's just past the worst part of the collapse, so keep an eye out for the quilboar.", completion = "I'm glad to know the others are safe. But not for long if we don't do something about these quilboar!", objectives = "Search the Deal Farmstead for any survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50625] = { id = 50625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Normal Random - Nth" }
quests[50626] = { id = 50626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Normal Random - 1st" }
quests[50627] = { id = 50627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Heroic Random - 1st" }
quests[50628] = { id = 50628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Heroic Random - Nth" }
quests[50632] = { id = 50632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield Scavenging", description = "The battle rages on, but our inventory suffers.\n\nScavenge the camps for supplies. I'll make use of what you find.You will be able to choose one of these rewards:", objectives = "Gather supplies from Newstead, High Perch and the Circle of Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50633] = { id = 50633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrible Ingredients" }
quests[50634] = { id = 50634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Our Scrolls!" }
quests[50635] = { id = 50635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shifting Tides", description = "I'm no tidesage, but even I can tell that whatever you have there is probably not a good sign for the bastion. \n\nThere's one of those Tortollans, Rikal, who's been helping us figure out a solution to whatever the naga are planning in front of the levee. He'd probably like to see this.", completion = "Hmm.... This is concerning. Very concerning.", objectives = "Speak with Rikal at Fort Daelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50636] = { id = 50636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravoracious" }
quests[50639] = { id = 50639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waycrest Manor: The Fallen Mother", description = "This is all a lot to process...\n\nThe Marshal... gone? My mother... the leader of the coven? It's just too much...\n\n...but we have come too far to turn back now. It is clear that my mother and father, as I knew them, are gone.  It is time we cleansed the taint from this land.\n\nWe must take the inquisitors and find them in Waycrest Manor. We will end this, once and for all.", progress = "This must be done.", completion = "I do not relish what we've done, but it was necessary for the good of Drustvar.\n\nI only hope the sacrifices we've made will be worthwhile in the end...", objectives = "Defeat Lady Waycrest in Waycrest Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50640] = { id = 50640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Question of Quillpower", description = "I can't believe you managed to kill that thing. You're quite impressive, you know that?\n\nEither way, we should be getting back to Roz with our report. We're stuck in the middle of the kraul, surrounded by angry quilboar. But I have a plan!\n\nSome of the boars seem reasonable enough. I gave them a bit of my rations and they've been following me around. I bet we can use them to hitch a ride out of this place. You in?", completion = "Calvin has briefed me, but I am eager to hear your report.", objectives = "Ride the Ornery Battleboar out of Briarback Kraul and report to Mayor Roz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50641] = { id = 50641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Their Ranks", description = "This temple is our last bastion against the Faithless. We need every able fighter to defend its walls. \n\nIf you're offering to help, we won't turn you away. \n\nHead into battle and do what you can to break their ranks!", progress = "We must defend the temple at all costs!", completion = "Our temple will not fall at the hands of the faithless!", objectives = "Kill 10 Faithless attackers within the Temple Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50642] = { id = 50642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Commands", description = "Silithus. That has been the name of the game... or rather, that is what I wanted the Alliance to believe. \n\nMake no mistake, Azerite is just as powerful as it is rumored to be but I have bigger plans in mind.\n\nHigh Overlord Saurfang is leading an army towards Silithus. By now, he should be in the Northern Barrens. I want you to intercept him and notify him that the preparations are complete.\n\nPreparations for what, you ask? Why, we are going to capture the World Tree.", completion = "I have been awaiting your arrival, {name}.", objectives = "Find Saurfang in the Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50644] = { id = 50644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing the Invaders", description = "While we try to figure out what to do with those channelers, we'll have to take shots where we can get them.\n\nOur men could use some assistance retaking parts of the lower walls. Kill some naga for me, would you?", completion = "Each one you killed is one less my men have to worry about. Thanks.", objectives = "Slay 15 of the naga forces invading Fort Daelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50645] = { id = 50645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eeling in a Big One", description = "If you are up to it, I have an idea to give the naga an amusing surprise.\n\n<Rikal slowly pulls out a scroll and waves it in your face.>\n\nI need some teeth from marine predators to cast the spell though. Luckily, the naga brought some disgusting eels with them. Go gather their fangs, and bring them back to me.", progress = "I can't wait to see how this goes.", completion = "That's exactly what I'm looking for. Give me a bit of time to prepare the spell.", objectives = "Collect 16 Abyssal Fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50646] = { id = 50646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quick Diversion", description = "I have halted our march until I received word that we were ready to divert.\n\nWhat comes next will be a coordinated, synchronized attack on key outposts in Ashenvale. If we act quickly, we will destroy the kaldorei's defenses and clear a path all the way to Darkshore. \n\nStormwind will surely send reinforcements to stop us. We have to conquer Teldrassil before they arrive.\n\nI will divert the troops. Meet with our operative, Lorash, outside Astranaar for further instruction.", completion = "Saurfang says it's time? Excellent.", objectives = "Find Lorash in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50647] = { id = 50647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everybody Has a Price", description = "Hundreds of rogues have already attacked kaldorei outposts in Ashenvale. On my signal, they will begin the next phase of this war: sowing chaos.\n\nMy colleague died not far from here, {name}, so I could use your help. If we stay out of sight, the town won't even know it's under attack before we have all of its guards down.\n\nI have a poison that will kill them quickly and silently. If you signal to me which targets are safe to attack without being noticed, I will put them down.\n\nWhat do you say?", completion = "We did it! Hopefully the other outposts fared as well as we did.", objectives = "Work with Lorash to disarm Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50648] = { id = 50648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbles and Trouble" }
quests[50649] = { id = 50649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filching from Thieves", description = "The naga oft take what they want with little care for who they are taking it from. Perhaps we should do the same for them.\n\nThe sorceresses use powerful beacons to assist with their spellcasting. I could use these relics to strengthen my own ritual.", progress = "Make sure you don't drop any of the beacons. I cannot say I know what will happen.", completion = "Ah! How powerful! These will be a great help.", objectives = "Collect 7 Tidal Beacons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50650] = { id = 50650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smashing Zalamar" }
quests[50651] = { id = 50651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Off Potential" }
quests[50652] = { id = 50652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biting the Hand that Feeds Them" }
quests[50653] = { id = 50653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming our Defenses", description = "We were holding off the naga up until the latest attack. A few of our forces are still out there.\n\nThe tidemaidens seem to be slowly torturing them to death. If you could save as many as you can find, we'd be one step closer to gaining the upper ground again.", completion = "That should slow down their progress quite a bit. You have my gratitude.", objectives = "Save 8 stranded battalion soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50656] = { id = 50656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Risky Rescue", description = "The Faithless incursion is just up ahead. \n\nWe tried to get ahead of the siege by attacking their camp in the dead of night, but they knew we were coming. \n\nOur troops were quickly overwhelmed. \n\nWe called for a retreat, but only a few of us made it out. The fate of those that didn't is unknown...\n\nWe don't have the numbers to attempt a rescue ourselves. We can't afford to lose any more fighters. \n\nYou're their only hope.", completion = "We are in your debt, {name}.", objectives = "Free 4 Temple Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50660] = { id = 50660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Strategy" }
quests[50665] = { id = 50665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cancel the Blood Troll Apocalypse" }
quests[50667] = { id = 50667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Past Due" }
quests[50668] = { id = 50668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Tides of War", description = "Champion, the Horde is now at open war with the Alliance.\n\nOur success in this conflict may depend on your skills.\n\nI require your immediate presence in Orgrimmar for a mission of the utmost urgency. Do not keep me waiting.", sourceObjective = "Speak with Nathanos Blightcaller in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[50670] = { id = 50670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doug Test - Gossip Test 3" }
quests[50672] = { id = 50672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Ammo Will Do", description = "I'll have some men move some cannons down to the sea wall in preparation of whatever ritual is going on down in that delta.\n\nWe could use some extra ammo before we spread ourselves too thin though. Luckily, those naga harpoons work well enough with our mortars. Take down those lances and bring back any harpoons that you find.", progress = "We can use the naga's weapons against them!", completion = "Great work! Let's hope these harpoons can fire from our cannons.", objectives = "Collect 20 Zeth'jir Harpoons on the coast south of Fort Daelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50674] = { id = 50674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Faced Pirate Scum", description = "We've been holding the Irontide off for days, but now they've brought in an ettin for reinforcements. We can't let him attack the town. \n\nA few of my best men just went up the hill to try and kill him. You look pretty capable, they could sure use your help?", progress = "Hurry {name} you've got to kill the ettin.", completion = "You've got skills we could use. You want join us and find the treasure before the Irontide?", objectives = "Eliminate Two Face Tom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50675] = { id = 50675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Hunting", description = "The workers are digging day and night out there to find the lost treasure. You'd get an equal share like everyone else, if ya wanna help out.\n\nTalk to Nedly about joining up.", completion = "I saw you killing those Irontide, you want in on our action?", objectives = "Speak to Nedly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50676] = { id = 50676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "River Toll" }
quests[50679] = { id = 50679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing the Shield", description = "I've been talking with Rikal, and the tortollan says that our problem in the delta can probably be solved by turning the naga's magic back on them.\n\nA few of the sorceresses on the south coast have a channeling wand that we may be able to use to break the head priestesses' ritual channeling. Find one, and bring it back here.", progress = "We cannot allow this fort to fall!", completion = "Even I can feel how much power this thing contains.", objectives = "Find an intact Zeth'jir Channeling Rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50689] = { id = 50689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's the Pits" }
quests[50690] = { id = 50690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flickering of Hope", description = "This pervasive darkness continues to cast shadows over our fields, hindering our harvests.\n\nCheck with Keyrra Flamestonge and see if you can help restore some order.", completion = "There is always work to be done, {name}. Your assistance in illuminating additional keyflames would instill hope and allow many here to return to work.", objectives = "Check in with Keyrra Flamestonge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50691] = { id = 50691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On Our Payroll", description = "The workers are complaining about elementals coming into the area while they're digging for treasure.  \n\nJust this morning, I had two people crushed to death! It's slowing down the hunt! \n\nYou can earn your share by getting rid of those elementals!", completion = "I almost trust you {race}.", objectives = "Eliminate 10 Restless Stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50694] = { id = 50694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Mess", description = "My order blesses every Kul Tiran ship within the halls of the Shrine of the Storm. Our blessings make our ships the strongest in all of Azeroth; the fleet of legend.\n\nThe ritual requires a substance known as tideblood. It is a viscous, powerful substance dredged from the depths of the sea and infused into the very hull of each ship.\n\nSomething has caused the tideblood here to become animate. Studying it may help us better understand our enemy.", progress = "The more tideblood you can bring me, the better.", completion = "Thank you. This will help us indeed.", objectives = "Collect 20 Tideblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50695] = { id = 50695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Never Time for Cannibalism" }
quests[50696] = { id = 50696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun With Magnets", description = "My last time in Tol Barad I had to leave in a big hurry, but I grabbed a few gadgets on the way out.  \n\nThis device is one of my favorites, so don't break it! It'll suck the treasure right out of the mud. It may make you tingle some, that's just the radiation.\n\nFind lost coins using the metal collector near the signs I've placed.", progress = "I like gold, let's find some!", completion = "You got the coins, and only mild radiation poisoning.", objectives = "Collect 60 Lost Coins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50697] = { id = 50697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomb Beats Rock", description = "I stole an old treasure map off an Irontide pirate. The map marks several caves on it with circles. \n\nThe caves are blocked by boulders, but now that you're here, we're going to open them up.\n\nYou get to do all the dangerous stuff, plant explosives, kill things, and cave exploring.  I'll supervise.", completion = "Boom!  Problem solved.", objectives = "East and West Caves blown open!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50698] = { id = 50698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problem Solving with Gunpowder", description = "Fort walls only go so far when it comes to defense. We've got cannons in position to fire if the naga get too close, but we need some fortifications further out.\n\nThere should be a few good areas to set up some traps further down the beach. Those naga will never know what hit them!", completion = "If you run across any other opportune spots, feel free to set up more mines.", objectives = "Set 5 Explosive Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50699] = { id = 50699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worker's Rights", description = "Hey, you! You lookin' for work?\n\nI ain't got a job for ya, but I can tell ya to stay away from Algerson Lumber!\n\nAlgerson'll promise ya some solid labor work and decent pay, but it's a lie I tell ya!\n\nThe conditions are terrible, we're gettin' attacked, and Algerson ain't even battin' an eye!\n\nHe don't care 'bout us little people. I'd stay away if I were you!", completion = "Why hello! Welcome to Algerson Lumber. How may I help you?", objectives = "Talk to Maynard Algerson at Algerson Lumber Yard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50700] = { id = 50700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drust in Time", description = "A few days ago, a band of Alliance researchers that called themselves the \"Explorers' League\" took a contingent of Kul Tiran soldiers to the old Drust ruins down the road.\n\nWe haven't really heard from them since, and I'm growing a bit concerned. I can't leave my post, so can you check up on the team?", completion = "We might have a wee problem on our hands.", objectives = "Find the Explorers' League members at the Thovas Base-Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50702] = { id = 50702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat Jakra'zet", description = "Jakra'zet is summoning Mythrax the Unraveler!\n\nWe cannot allow the ritual to continue. Jakra'zet must be stopped before it's too late!\n\nLead the way, {name}. We'll be right behind you.\n\nLet's go!", completion = "It's a miracle we survived...", objectives = "Defeat Jakra'zet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50703] = { id = 50703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", completion = "I shall inform the Dark Lady of your activities in Vol'dun at once. She will know how to best proceed against this  new threat.", objectives = "Speak with Baine Bloodhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50704] = { id = 50704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anchors Aweigh Too Much", description = "I got a little deal on the side, selling used ship parts to Addington Shipyards.\n\nWhile you're out looking for the treasure, see what sort of useful parts you can salvage from the mud: anchors, cannons, whatever!\n\nWe'll sell them to Addington and cut you in for a share of the profits.", progress = "See what you can find out in the mud.", completion = "We'll make good money off these. No one will know they are used parts.", objectives = "Find 12 Old Ship Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50705] = { id = 50705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Snake with Three Heads", description = "Now that all of the preparation has been done, it's time to tackle the main threat.\n\nYou can use the channeling rod you just found in conjunction with this scroll I got from Rikal to break the shields around the naga leaders in the delta.\n\nHurry! Stop them before they finish their summoning!", completion = "Well, the bubble seems to be gone, but I don't like the looks of that whirlpool.", objectives = "Slay the three naga channelers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50706] = { id = 50706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Delta", description = "The greatest of the Zeth'jir offensive sits within the delta as we speak, waiting for the summoning ritual to be finished. If we can clear out a number of them, we'll finally have the upper hand.\n\nGet down there and cause as much chaos as you can!", progress = "This fort will always stand in defense of Kul Tiras!", completion = "Good work! That should deter the naga for now.", objectives = "Kill 15 naga forces in the Eventide Delta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50717] = { id = 50717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stalk Me, Troll" }
quests[50718] = { id = 50718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agent of Death" }
quests[50733] = { id = 50733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Dawn", description = "House Stormsong may be lost, but this valley still holds so much hope. \n\nSam knew that from the beginning.\n\nWe have to continue to help the Storm's Wake in any way we can. There are still remnants of the fallen house everywhere, and whoever turned them to this darkness is out there as well.\n\nCyrus and the others will want to hear about everything that happened. We should tell them together.", completion = "I've filled them in on most of the details already. The Storm's Wake will be an invaluable ally if we're to reunite Kul Tiras.", objectives = "Meet Taelia in the Harbormaster's Office in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50735] = { id = 50735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burial Detail" }
quests[50737] = { id = 50737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence the Speakers" }
quests[50738] = { id = 50738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timely Arrival", description = "My end of the bargain is done, {race}. \n\nI am going to check on the other outposts to make sure none of my brothers and sisters are in trouble. Meet with the Warchief and inform her that Astranaar has been secured. If everything has gone according to plan, she should be well on her way.\n\nOh, and try not to hog all the glory, yeah? \n\n<Lorash smirks at you>.", completion = "That was a perfectly executed strike, {name}.", objectives = "Greet Warchief Sylvanas Windrunner in Astranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50739] = { id = 50739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Business", description = "Poor little Coda has been in quite the tizzy since his friends vanished. \n\nI found him here, out cold, after a sting from one of those awful wasps. Just a tiny bit of our sandstinger remedy got Coda right up, though!\n\nTake some with you, and keep an eye out for other little ones out there.", progress = "Did you find them all?", completion = "Oh thank goodness! We'll have to keep these little guys away from anything with a big mean stinger out here. Man, I'm going to be busy. \n\nIf you could protect Coda's little brother, that would help us out a lot!\n\nThis is Poda!", objectives = "Rescue 7 Sable Polecats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50740] = { id = 50740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoram'gar Outpost", description = "Saurfang shall establish our troops here, now that Astranaar is ours. I shall continue my hunt for the only creature that can stop our march to victory: Malfurion Stormrage.\n\nOur next order of business will be to establish a foothold at the base of Darkshore. Commander Grimfang of the Zoram'gar Outpost should be able to accommodate an incoming army.\n\nInform him of our arrival and ensure the necessary preparations are made.", completion = "A force this large has not moved in Ashenvale in a long time. I hope Zoram'gar is ready to accommodate the might of the Horde.", objectives = "Make the necessary preparations at the Zoram'gar Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50741] = { id = 50741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Turtle", description = "There's a Tortollan who's trying to get our treasure! He's over on the west side of town.  He's nosey and he may have found something!\n\nTalk to Moxie. Come up with a plan to get rid of him.", progress = "You deal with that Tortollan yet?", completion = "Worm meat for the box full of treasures!  You sure you're not a Goblin?", objectives = "Speak with Moxie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50742] = { id = 50742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Laid Out For Us", description = "<This is all the treasure Calico McGee's found so far. Packed up and ready to move out. More like all laid out for you to take!\n\nYou'll need a few extra hands to carry this much loot. There should be some Treasure Hunters from Deadwash around.\n\nAsk Big Find Balor, Toothless Eddard, and Chopper Darry to help.>", completion = "Plundered McGee's treasure? Who's the pirate now!", objectives = "Get three treasure hunters to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50743] = { id = 50743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Immediate Problem", description = "I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction.\n\nWe need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.", sourceObjective = "Speak with Lieutenant Bauer.", sourceObjectiveStatus = "unverified-source-field" }
quests[50744] = { id = 50744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refresh Their Memory" }
quests[50745] = { id = 50745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Empire", description = "The heart of the Faithless empire rests just beyond this ridge. We will need to move swiftly and quietly to avoid detection once inside.\n\nThankfully, my former dwelling is nearby. I know a passage that should allow us to advance into the fortress with minimal resistance. When you are ready, speak with me and I will show you the way.\n\n<Vorrik looks around suspiciously.>\n\nI expected the Faithless to patrol this area... Keep your eyes open for anything suspicious along the path.", completion = "It's unconventional, but I believe Sethraliss would be pleased to see her shrine used to protect innocents in need.\n\nAnd if these vulpera are fighting the Faithless, they will be useful allies.", objectives = "Accompany Vorrik to his sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50746] = { id = 50746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crater Conquered", completion = "I can hear the vulpera battle cries from here. It seems your friends have given us a window of opportunity. We musn't waste it.\n\nI have a plan.", objectives = "Return to Vorrik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50747] = { id = 50747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Good Amani" }
quests[50748] = { id = 50748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Drop It... Yet", description = "The Faithless are training pterrordaxes as mounts so that they can rain down death from the skies.\n\nTheir skycallers have developed a means of storing volatile lightning magic into fragile crystals. Lightning bombs, in the simplest sense. The magic behind it is quite brilliant, really.\n\nThe bombs will be exceptionally useful if we can secure the aid of Rakjan, the powerful and fierce pterrordax at the top of this mountain.\n\nAcquire as many as you can carry, while I will do my best to recruit Rakjan.", progress = "There are no end to the Faithless, so grab as many as you can carry.", completion = "Excellent! Rakjan appears willing to aid us, so we will certainly make good use of these.", objectives = "Collect 6 Volatile Lightning Bombs from Faithless.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50749] = { id = 50749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Ride", description = "One thing I've learned during my time in Vol'dun is to not stay in one place for too long. And doubly so when the Faithless are involved.\n\nWe've done our damage here. Let's move before we get caught.\n\nI procured a mount to take us back to Meerah and the others in Vorrik's Sanctum quickly. Don't worry, this Faithless won't be needing it anymore.", completion = "I'll have some of the vulpera stable that krolusk outside, in case we need to use it again.", objectives = "Steal the Battle Krolusk mount and return to Meerah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50750] = { id = 50750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infuriating the Emperor", description = "It seems I underestimated Korthek's cowardice. I expected him to be behind the barrier, ready to ambush us. Yet, still he hides.\n\nThat allows us a few moments to prepare. We musn't waste them.\n\nWhile I siphon power off of these immense crystals, you must thin the numbers of the Faithless here. I will grant you a powerful boon to speed you in your task.\n\nWhen Korthek arrives, he will require our full attention.", completion = "Excellent. Now we may focus on Emperor Korthek without distractions.", objectives = "Use Vorrik's Bulwark to defeat 75 Faithless within the Sacred Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50751] = { id = 50751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctuary Under Siege", description = "I fear that Emperor Korthek was not lying when he boasted of his foolish plan.\n\nIf General Jakra'zet attacked the Sanctuary of the Devoted while we were away, there is a good chance that he now has everything needed to resurrect Mythrax.\n\nWe must hurry to the Sanctuary and stop Jakra'zet. Mythrax must not be reborn!", completion = "We're too late. The keys are gone. \n\nSethraliss... What have I done?", objectives = "Meet Vorrik at the Sanctuary of the Devoted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50752] = { id = 50752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of Sethraliss", description = "It may surprise you to learn that the Faithless hoard ancient relics of Sethraliss. I assure you that they do not do so out of reverence or respect, as is proper.\n\nKorthek's brood is driven only by greed and an insatiable lust for power. They rip whatever magic they can from the relics, even if it means destroying them in the process.\n\nRescue the ancient artifacts of Sethraliss in the Sacred Sands nearby. We will honor and preserve them in the Sanctuary of the Devoted.", progress = "Do you have the artifacts?", completion = "Incredible! I remember when some of these were first found...\n\nYou've done all followers of Sethraliss a kindness this day, {name}.", objectives = "Recover the Skull of the First Skycaller, Rebirth Creed, Sethraliss Sight Stone, and Blood of the Fallen Loa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50753] = { id = 50753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earl-E Bot Gets the Worm", description = "It could take you days to get that much meat, and I don't want to wait around. So, we'll use a Bot as bait!  \n\nYou send EARL-E towards any disturbances you see in the mud. He'll make enough noise to scare any worms out.  \n\nThen kill the worms, get the meat. I'll watch from here.", progress = "Do you have the meat yet?", completion = "This will make a nice Mud Worm Soup. I wasn't liking this box anyway.", objectives = "Get Mud Worm Meat for Maokka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50754] = { id = 50754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Have Loved and Lost", description = "I have a favor to ask you of a... personal nature.\n\nWhitegrove Chapel lies to the north, just past the town of Corlain. Someone... important to me rests in the graveyard on its grounds.\n\nI've been unable to visit his grave for some time, and I would like to pay my respects. If you come upon Whitegrove Chapel, could you lay these flowers next to his headstone?\n\nJust look for the most recent grave there...", completion = "Lucy sent you? I am relieved to hear she yet lives. \n\nMy name is Alexander Treadward. I am... well, I was Lucy's fiance.", objectives = "Lay the Crimson Bouquet next to the Simple Gravestone in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50755] = { id = 50755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meal for Birds", description = "I don't know why I agreed to this. We weren't supposed to be scavenging. \n\nKiro gave me specific instructions to head to the basin and feed the buzzards.\n\nI can't go back to camp until they eat, but I'm not heading into that basin while the sethrak are still swarming. \n\nHave you ever fed a buzzard? It's easy, I promise. \n\nYou kill it, they eat it. That simple.", progress = "They still look hungry to me.", completion = "I don't think I've ever seen these buzzards so satiated. How much did you feed them exactly? \n\nDoesn't matter. You saved my tail, for sure.", objectives = "Kill wildlife within The Brine Basin so Mekaru's buzzards can eat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50756] = { id = 50756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subterranean Evacuation" }
quests[50757] = { id = 50757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untame Slaughter", description = "The Faithless rely on their krolusks for everything. They are mounts, battle companions, beasts of burden, and often even food to fuel the sethrak empire.\n\nIf we can disrupt their krolusks, we'll disrupt their whole empire. One broken wheel stops the caravan, eh?\n\nTake out as many of their krolusk tamers as you can. That'll have a longer impact than just killing the krolusks.", completion = "The Faithless will be nursing that wound for awhile. Well done.", objectives = "Kill 8 Faithless within the Feeding Pits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50758] = { id = 50758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Painful Memories", description = "A terrible thing happened in this place, and it has doomed me to an eternity of walking these grounds.\n\nAll I remember is that Lucille and I were to be wed, but instead I met my end.\n\nIf you have an ounce of sympathy in your heart, then I beg you to help me. Find out what happened that night, so I might leave here.\n\nI know my strongest memories are tied to the ring I bore for Lucy that day. Find it among my bones, and maybe it will lead you to the answer.", completion = "Welcome, kind sir!\n\nThe ceremony should begin as soon as the good Lord Waycrest arrives.", objectives = "Search the Forgotten Bones for Treadward's Ring in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50759] = { id = 50759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Late", description = "I beg your pardon, but I am a little concerned at Lord Waycrest's tardiness.\n\nI'd hate to be a bother, but would you mind checking on him? The ceremony awaits his presence.\n\nYou can find him in the bride's room, at the top of the tower.", progress = "It must be around here somewhere...", completion = "Splendid! I'll just need to take a few moments to go over this and I'll be right down.\n\nPlease let Lucy and Alexander know I will be ready shortly.", objectives = "Speak with Lord Arthur Waycrest in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50760] = { id = 50760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From This Day Forward", description = "Lord Waycrest is on his way? Excellent!\n\nYou have my thanks, <sir/madam>. Please, take a seat.", completion = "What is going on here!?", objectives = "Take a seat and observe the wedding ceremony in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50761] = { id = 50761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Chapel", description = "<Sir/Madam>, you have helped me before and I beseech you to do so again.\n\nMy guards are clearly outnumbered by these brigands. I must stay here to protect Lucille, so I will need you to assist in protecting the guests.\n\nAre you able?", progress = "We must rout these knaves!", completion = "Well done! My guards seem to have gained the upper hand, thanks to you.\n\nBut wait... where is Meredith?", objectives = "Defeat 10 Red Hand Assassins in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50762] = { id = 50762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lady's Fate", description = "Meredith never joined the ceremony. She might be in trouble!\n\nLucy is in shock, and I cannot leave her here. You must go in my stead to the tower, and ensure the safety of your Lady.\n\nDo this for me, and you will be rewarded.", progress = "What have you found?", completion = "Her mother ordered the assassination!?\n\nI had known that she didn't agree with Lucy marrying a merchant, but I would never suspect she would go so far to prevent it!\n\nThank you, {class}.", objectives = "Find Lady Meredith Waycrest in Whitegrove Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50763] = { id = 50763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Request", description = "I can feel my bonds to this place slipping, and I have you to thank.\n\nI would like to ask one more favor of you though. Please bring the ring you found to Lucille. It was meant for her to hold, not my dusty bones.\n\nAnd {class}, do not tell her what has transpired here. She has enough tragedy weighing down her heart. I do not wish to add to it.", progress = "What... what's this?", completion = "This... this is the ring Alexander was to give me at our wedding.  I had thought it long lost...\n\nI do not know how you found this, {class}, but words cannot say how grateful I am. Alexander was very dear to me, and this ring was a symbol of the strength of our love.\n\nIt is good to feel that again...", objectives = "Bring Treadward's Ring to Lucille Waycrest at Watchman's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50765] = { id = 50765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herding Children" }
quests[50767] = { id = 50767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scrimshaw Gang" }
quests[50769] = { id = 50769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stormwind Extraction", description = "My lady is shrewd indeed. If we are to infiltrate Stormwind City, we will need the very best the Horde has to offer, and yet a team so small as to be able to infiltrate the heart of Alliance territory unseen.\n\n<Nathanos peers at the gathered group, stroking his chin.>\n\nYes, I see.\n\nThe path ahead is clear. Speak to me when you are ready to undertake the Warchief's mission, {name}.", progress = "We must not fail the Warchief.", completion = "Well, here we are. Zuldazar. We had better stick with Talanji and Zul for now. The Warchief will be interested to know what happens next.", objectives = "Complete \"The Stormwind Extraction\" scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50770] = { id = 50770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effective Antivenom", description = "The salve is ready. \n\nI work fast. Hopefully faster than the scorpid poison. \n\nTake this antivenom to your friend and see that he swallows every last drop. \n\nYou should know within moments if it's been effective.", completion = "Thank you for saving my life. I'm afraid we don't have time for formal introductions.", objectives = "Administer the Antivenom to Serrik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50771] = { id = 50771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calldown: Cleaner", description = "With these dust blowin' siro-ma-whosits all over this beach front, it's a pain to get our cleaners out onto the nodes.\n\nSome of the crew wanted to check somewhere else, but no way we're leaving without those rocks for Gallywix. \n\nBetween you and me, {class}, we're gonna be gettin' some serious hazard pay for this gig.", progress = "All the resources been harvested?", completion = "Not bad, chief! The crew should be wrapping it up soon.", objectives = "Identify and mark 5 Azerite deposits for the extraction team.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50772] = { id = 50772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Prowl", description = "Do you see all of the wisps about? I have seen this once before, when the demon Archimonde was felled by the sting of hundreds - no - thousands of wisps.\n\nThis can mean only one thing. Malfurion is beckoning the aid of his ancestors.\n\nThe Warchief has already taken a scouting party ahead to Darkshore to intercept him. Please, {name}. Find the Warchief and see if she has yet caught her prey. \n\nWe have secured all of Ashenvale, but we must keep the pressure on.", progress = "You may approach, {name}.", completion = "I've been tracking Malfurion's every movement. The lord of the forest cannot hope to outmatch one who served as Ranger-General of Silvermoon.", objectives = "Find Warchief Sylvanas Windrunner in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50773] = { id = 50773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're a Shark", description = "Have you ever been bitten by a shark? I have, numerous times. It stings.\n\nMurlocs don't usually survive shark attacks.\n\nThe ritual I had in mind is ready to cast. Let me know when you're prepared.", progress = "I can't wait to see how this goes.", completion = "How did it feel to be a murloc's greatest fear?", objectives = "Kill 20 murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50774] = { id = 50774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Bot Left Behind", description = "You left Earl-E behind, and a giant worm ate him! He's got sentimental, uh... monetary value. \n\nWe don't leave any bots behind!\n\nKill that worm and get Earl-E back.", progress = "What? Earl-E isn't going to help himself!", completion = "You saved Earl-E! I am forever grateful {race}.", objectives = "Help Earl-E.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50775] = { id = 50775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Us Some Beach", description = "These guys are running out of \"ammo\" faster than we can replace it! \n\nI tells 'em, we're on a beach, you're in a sandblaster, suck it up!\n\nThey says it's against the cleaner driver rules for their local chapter.\n\nI'm not buyin' it.\n\nGrab us some more sand. Them sand monsters have gotta be full of the stuff!\n\nWe'll make it worth your time.", progress = "Ya get us the dirt yet?", completion = "That should fill us up a few more bags. If they run out again, I'll make 'em break out the pickaxes.\n\nI bet then a little self-fueling won't sound so bad!\n\nUngrateful sons of bellybutton lint...", objectives = "Collect 20 piles of sand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50776] = { id = 50776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Prophets" }
quests[50777] = { id = 50777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm Awakens", description = "I must watch over Samuel for now. I fear for the darkness assaulting his mind.\n\nThe fallen men and women around us were defectors from the house. There will be more like them within Sagehold. \n\nFind them, and tell them 'the storm awakens'. Knowledge of our cause has spread; we need to bring all we can to our side.", progress = "Find all you can who will stand with us. We are stronger united.", completion = "I saw some of the defectors leaving. I'm glad we got to them before Lord Stormsong did.", objectives = "Rally 12 Defectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50778] = { id = 50778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Intentions", description = "Sails... in the fog...\n\nA light below... in the darkness.\n\nWater rising... given form... the pain... \n\nAHHHH, THE PAIN!\n\nMake it stop. Make it stop. Make the pain stop!", progress = "I know Sam is unwell, but I think he's onto something.", completion = "Their rituals are growing bolder. Sooner or later they're going to summon something they can't control.", objectives = "Kill the Bound Tempest and Enthralled Tidefury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50779] = { id = 50779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clean Slate" }
quests[50780] = { id = 50780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oathbound", description = "I took oaths, damn it. We all did.\n\nWhen Lord Stormsong sent the first orders... well, you saw what happened. What matters is that our oaths are to our people, not Lord \"Sells His Soul\".\n\nYou won't find him here - he's deep in the Shrine by now, and no outsider will make it across the channel alive...\n\nNot without a Tideguard to open the way.\n\n<Victoria locks eyes with you.>\n\nThe Rod of Tides is the key to the front door, and it's kept here. Retrieve it and I can get you to him.", progress = "You do have the rod, right?", completion = "I see it deemed you worthy. Good.", objectives = "Retrieve the Rod of Tides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50781] = { id = 50781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bridge Too Far", description = "The bridge that once crossed this span is the only land route to the Shrine. \n\nIt appears Lord Stormsong has sealed it to buy himself more time. We have been attempting to reopen the way to no avail.\n\nHowever, the Rod of Tides you recovered may prove our solace. Veteran tideguards use it as a key of sorts to maintain the Path of Storms across these dangerous waters.\n\nWe will begin the ritual once more... if you will wield the rod.", progress = "Now that Lord Stormsong is aware of our intentions every moment is precious.", completion = "The way is opened at last.", objectives = "Use the Rod of Tides to open the Path of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50782] = { id = 50782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word on the Streets" }
quests[50783] = { id = 50783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abyssal Council", description = "The tidesages have a leading council beneath Lord Stormsong. They each oversee a different aspect of the order's work.\n\nWavespeaker Reid trains initiates here in the oldest form of tidesage magic: communing with the sea.\n\nThese deaths are on his hands. It's up to us to take him down.", completion = "Well, Lord Stormsong's definitely aware of us now.", objectives = "Kill Wavespeaker Reid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50784] = { id = 50784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of the Storm", description = "If Lord Stormsong wasn't aware of you yet, he is now. Your best shot is to reach him at the Shrine of the Storm before more of his followers fall back to his defense.\n\nI can get you in, but you'll have to protect me. I'm in no shape to take down any more of these fiends.\n\nAnd try to keep a low profile. The closer we get to the Shrine, the more power Lord Stormsong has at his disposal.", completion = "This is the only way into the Shrine of the Storm.", objectives = "Escort Tideguard Victoria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50786] = { id = 50786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge of Krag'wa" }
quests[50787] = { id = 50787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Our Case", description = "Katherine has trusted Priscilla Ashvane as an advisor and a close friend for many years, even before they both lost their husbands at Theramore.\n\nShe's heard the rumors about Ashvane, just like anyone. Whether by fear or loyalty, she's chosen to ignore them.\n\nIt's time to finally open her eyes.", completion = "Damnit! Where'd she go?!", objectives = "Reveal Lady Ashvane's treason to Katherine Proudmoore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50788] = { id = 50788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Within", description = "We need to get Katherine to safety.\n\nHelp us take out some of these traitors!", objectives = "Slay 6 Ashvane combatants in Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50789] = { id = 50789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Air", description = "Looks like Priscilla had a backup plan. Her goons set off some kind of smokescreen to cover her escape.\n\nClear out that smoke so the civilians can evacuate and we can secure the area!", objectives = "Destroy 4 Smoking Payloads in Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50790] = { id = 50790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Pursuit", description = "Priscilla's escaping on horseback! Grab one of our chargers and chase her down!", completion = "I don't know how anyone could survive a fall like that.\n\nStill, we should be careful not to let our guard down.", objectives = "Mount a Proudmoore Charger and chase Priscilla Ashvane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50791] = { id = 50791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skree...", description = "<Kua'fon rests with his head under his wing.>\n\nSkree...\n\n<Perhaps the little guy could use a display of affection to raise his spirits.>", completion = "<Kua'fon rubs his face against your hand.>\n\nSkree.", objectives = "Soothe Kua'fon by picking him up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50792] = { id = 50792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Bribes" }
quests[50793] = { id = 50793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave Commotion", description = "Killing that worm stirred up a commotion in the caves below. The Irontide seem pretty excited. We better check it out.\n\nNedly's on his way, meet us near the caves.", completion = "It's the Irontide! They've found treasure in the caves below us!", objectives = "Meet up with Nedly and Moxie near the caves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50794] = { id = 50794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Shelter", description = "I must head back to de arena. Razgaji will want to know what happened here. \n\nIf you seek shelter, you will find it at de outpost not too far from here.\n  \nI will let our leader know you're coming.\n\nBe safe, {name}.", completion = "Yes, Julwaba told me to expect you.", objectives = "Find Razgaji at the Scorched Sands Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50795] = { id = 50795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Trouble", description = "With the evidence you've gathered, we can prove that the Ashvane Company was behind the attack.\n\nI would have preferred to do this in private, but I don't think we'll have the luxury. Look around - company men everywhere. \n\nPriscilla's got something up her sleeve...\n\nLet's get some backup before we go in there and cause a scene.", completion = "Alright. It's time.", objectives = "Speak with 4 Proudmoore Guards in Unity Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50796] = { id = 50796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEEEEEE!!!\n\n<You know what to do.>", progress = "SKREEEEEEEEEEEEEEEEEEE!!", completion = "<Kua'fon licks his chops and sighs contentedly.>\n\nSkree.", objectives = "Feed Kua'fon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50797] = { id = 50797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Turtle's Invitation", description = "You have been most helpful {race}. Please visit me and the other Tortollans along the Jeweled Coast.  \n\nWe'll discuss soup and other pressing matters.", completion = "You're arrival is most timely. We could use your help!", objectives = "Visit Maokka and the other Tortollans at the Jeweled Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50798] = { id = 50798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out on a Limb", description = "Ah, there you are.\n\nKua'fon ran off into de jungle. I saw him head down de western path out of the Kraal but beyond that I could not say where he may have gone.\n\nThis kind of thing happens with the young. Our winged companions have a keen sense of adventure!\n\nIt would be helpful if yours could fly, but it is not yet time. I would check any reasonably high place that he could climb to, as a start.", completion = "<Kua'fon seems mighty pleased with himself.>\n\nSkree.", objectives = "Find and rescue Kua'fon in the Slough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50800] = { id = 50800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Woods", description = "Careful, {name} -- the forest is still brimming with Stormrage's forces...\n\nLook out behind you!", completion = "Malfurion will soon return with an army.", objectives = "Defeat the Alliance ambush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50801] = { id = 50801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for Ptrouble", description = "Ah, yes, I was wondering when you would come to check on your little one.\n\nAs you have likely noticed, he is not here. Little ones are very curious and often seek to leave the nest before they are ready. It is often the brooding mother's job to keep them from wandering.\n\nWhat, did you think I was going to stop him?\n\n<Wingminder Goja laughs.>\n\nI heard some screeching to de west. Best hurry, or you may not have a hatchling to look after!", completion = "<Kua'fon makes a soft sound deep in his throat. He seems very pleased with himself.>", objectives = "Find Kua'fon in the Slough and rescue him from danger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50802] = { id = 50802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Low Tide", description = "A few years ago I tried to join the Irontide. They said I wasn't \"Irontide material\", not cruel or heartless enough! \n\nSo I teamed up with Nedly and Moxie here in Deadwash, and we started looking for treasure on our own.  \n\nLet's show these Irontide they're not \"Deadwash material\".", completion = "No one's gonna cry about a few less pirates.  I may even dance about it!", objectives = "Kill 10 Irontide Pirates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50803] = { id = 50803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Want It All Now", description = "These Irontide Raiders think they can just come in and take the treasure we've been hunting for months!\n\nBy rights, that treasure is ours! Get in there and get our share of it, before it's gone.  \n\nBy share, I mean all of it!", progress = "I want every piece of that treasure in there.", completion = "I'm going to be a rich man! You're not holding out on me are ya?", objectives = "Collect 12 Irontide Coin Bags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50805] = { id = 50805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skycaller Shutdown" }
quests[50808] = { id = 50808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halting the Empire's Fall", description = "Nazmir be havin' problem after problem, {name}. I not be knowin' how it can get much worse dan an Old God tryin' ta take over.\n\nI be makin' me way back ta Zul'jan ta lead our efforts ta keep Nazmir safe.\n\nYa should return ta Zuldazar and let Baine know what be goin' on here. Maybe he be likin' dis here underrot, who knows?\n\nI can get ya outta here and back ta Zul'jan, if ya be needin' it.", completion = "So, an Old God lurks beneath the swamp and it's barely being contained?\n\nUnbelievable. Princess Talanji was right in calling her father a fool. How could he let such a thing stay so close to his empire?\n\nI will ensure that the warchief knows of your victory... and of our new problem.", objectives = "Speak to Baine Bloodhoof within Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50810] = { id = 50810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break 'Em Out", description = "An Irontide captain \"Calico McGee\" has been trying to scare us off for days now, but it's not working.\n\nHe's ordered his men to lock everyone up and sell us as slaves! They've brought enough chains for everyone!\n\nBreak the chains and set our workers free.", completion = "With everyone free, we can get back to finding the treasure!", objectives = "Free 10 workers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50812] = { id = 50812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakened Elements", description = "It seems that all of this infernal blasting and hammering has stirred up... something.\n\nI heard some screaming from over in that direction.\n\n<He gestures vaguely to the north.>\n\nIf you could go take care of the situation, that would be most appreciated.", progress = "Did you remove the impediment?", completion = "That's better. Not sure how we were going to turn a profit if we had to keep replacing workers.", objectives = "Investigate the disturbance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50813] = { id = 50813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cargo Reclamation" }
quests[50814] = { id = 50814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Horrible Place", description = "This town is a horrible place full of bad people. All they care about is money! No one cares about the turtles!\n\nThe turtles are out there, thirsty, drying up, and getting stepped on by monsters!\n\nYou have to save the turtles for me!", completion = "They're still moving! Emma's going to be so happy they are still fresh!", objectives = "Collect 6 Wetshell Turtles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50817] = { id = 50817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charming Tail", description = "I think they would make great guardians, when they get older... with the proper training.\n\nHowever, it seems some of my trainees have wandered off. There are so many things nearby that could harm them!\n\nBetween the walking sandstorms and angry plants... it's been safer to hide out here and look at night.\n\nI'm so exhausted! \n\nCould you take this flute with you and play them a little tune? It will remind them to come back to me.", completion = "Yes! Thanks, {name}! They are so much happier now!", objectives = "Send 15 cobras to Jenoh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50818] = { id = 50818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Flute", description = "<This little flute, while dusty, appears to be well cared for.\n\nIts owner can't be too far away.>", completion = "My flute! I've been looking everywhere!\n\nWell, sort of...", objectives = "Find the owner of the Desert Flute.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50823] = { id = 50823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ripe for the Picking", description = "The kaldorei have finally halted our progress. In a perfect world, we could have marched all the way to Auberdine and taken Teldrassil before they could even slow us down - but it matters little.\n\nMalfurion will try to hold us back until his fleet returns from Silithus. Until then, his army is too small - if only we could find a path through these damned wisps.\n\nI have an idea. Let's have a chat with Saurfang.", completion = "The kaldorei have begun to reinforce Darkshore. Our path to Teldrassil will be more difficult than we had anticipated.", objectives = "Meet with Saurfang and Sylvanas in the Zoram'gar Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50824] = { id = 50824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's End", description = "I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. \n\nWe have him surrounded, cornered like the rat he is. We must end this together.", completion = "Samuel was a good man, with a true heart. A fool... but our fool.", objectives = "Confront Lord Stormsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50825] = { id = 50825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Storm: Whispers Below", description = "We must not let Lord Stormsong finish his work.\n\nIf he delivers the fleet to Azshara, all of Kul Tiras will be vulnerable. Countless innocents will perish -- or worse.\n\nThere is no time to wait for more of the Storm's Wake to arrive. We finish this now, for the good of all who call this valley home.\n\nWe finish this for Samuel.", completion = "I pray we are not too late. The fleet must return home.", objectives = "Defeat Lord Stormsong in the Shrine of the Storm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50834] = { id = 50834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep It Down!", description = "There is a lot of noise and light coming from those filthy mechs down by the shore. No wonder my  little hatchlings get so cranky!\n\nThey are shaking up a coast that is already unstable. You never know what one might wake up that way! \n\nLet them know they should be careful.", completion = "Dangerous? Violence incoming? Tell us somethin' we don't know!\n\nWe ain't goin' nowhere until we get what we came for!", objectives = "Warn the goblins of danger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50835] = { id = 50835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Port of Zandalar", description = "King Rastakhan has given me orders to investigate de Harbor of Zandalar. De claim Princess Talanji has levied against General Jakra'zet for failing to maintain de safety of our kingdom is a serious accusation.\n\nFor dis task, I would have you join me so dat I might have an outside perspective. When you are ready, meet me in de Grand Bazaar.", completion = "Let us get to work.", objectives = "Meet Zolani in the Grand Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50837] = { id = 50837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quick Flyover", description = "Malfurion knows that his wisp wall is a temporary measure. He is buying time for reinforcements to arrive in Teldrassil.\n\nIt is imperative that we find a way through that wall, and quickly.\n\nI want you to take our explosive reserves and apply pressure. You will not be able to bring it down, but you may be able to find us an opening. I will have a squadron ready to strike once you break ground.\n\nZarvik Blastwix should have a few bombardiers for the job.", progress = "Done?", completion = "How did it go?", objectives = "Use explosives to fend off the Alliance army in Darkshore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50838] = { id = 50838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for Ptrouble", description = "Ah, so you noticed he is missing again.\n\nI would check de east this time. I heard some screeching from that direction.\n\nI am sure he will be fine- after all, what sort of trouble could he get in with you looking after him?\n\n<Wingminder Goja smiles just a touch sarcastically.>\n\nBest find out.", completion = "<Kua'fon casually inspects his wings for damage. He seems very smug.>", objectives = "Find Kua'fon in Atal'Gral and rescue him from danger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50839] = { id = 50839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", progress = "<Kua'fon inspects your hands for food and shrieks demandingly at you.>\n\nSkree!", completion = "<Kua'fon gurgles in satisfaction.>", objectives = "Feed Kua'fon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50841] = { id = 50841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", completion = "<Kua'fon licks his chops. His head bobs in satisfaction.>\n\nSkree.", objectives = "Feed Kua'fon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50842] = { id = 50842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mast Effect", description = "Kua'fon was peering over de edge and managed to fall off de cliff again.\n\nNormally he gets back up here on his own, but it be taking too long this time.\n\nBest go down to de beach and find him. He is probably stuck up one of de ship masts out there.\n\nIf he will not come down, you can try bribing him with more fish.", completion = "<Kua'fon picks at his teeth with a wing-claw, carefully avoiding eye contact with you.>", objectives = "Find Kua'fon in Talanji's Rebuke and bribe him down with fish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
