quests[50859] = { id = 50859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandak" }
quests[50860] = { id = 50860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nose for Ptrouble", description = "Kua'fon is getting very large. Perhaps he thinks himself equal to de beasts of this jungle.\n\nHe may well learn that he is not. You should find him before that lesson costs him his life.\n\nI heard a commotion to de north. Start there.", completion = "<Kua'fon spreads his wings and utters a piercing shriek. He had it the whole time.>\n\nSkree!", objectives = "Find Kua'fon in the Savagelands and rescue him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
